+.grid4{ display:grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 12px; }
+.miniCard{
+  padding: 14px;
+  border-radius: var(--radius-lg);
+  border: 1px solid rgba(17,19,21,.10);
+  background: rgba(255,255,255,.92);
+  transition: transform .12s ease, box-shadow .2s ease;
+}
+.miniCard:hover{ transform: translateY(-1px); box-shadow: 0 22px 48px rgba(17,19,21,.08); }
+.miniCard .thumb{
+  height: 92px;
+  border-radius: 16px;
+  background: radial-gradient(circle at 20% 20%, rgba(255,122,89,.30), transparent 55%),
+              radial-gradient(circle at 70% 10%, rgba(2,131,141,.28), transparent 55%),
+              linear-gradient(135deg, rgba(2,131,141,.10), rgba(245,158,11,.10));
+  border: 1px solid rgba(17,19,21,.08);
+  position:relative;
+  overflow:hidden;
+}
+.miniCard h4{ margin: 10px 0 0; font-size: 14px; letter-spacing:-0.02em; line-height:1.25; }
+.play{
+  position:absolute;
+  inset:auto 12px 12px auto;
+  width: 40px;
+  height: 40px;
+  border-radius: 999px;
+  background: rgba(255,255,255,.92);
+  border: 1px solid rgba(17,19,21,.10);
+  display:grid;
+  place-items:center;
+  box-shadow: 0 18px 30px rgba(17,19,21,.12);
+}
+
+/* Footer */
+footer{
+  border-top: 1px solid var(--border);
+  background: rgba(255,255,255,.78);
+  padding: 22px 0;
+}
+.footerGrid{ display:grid; grid-template-columns: 1.3fr 1fr; gap: 16px; }
+.footerForm{ display:flex; gap: 10px; flex-wrap:wrap; }
+.footLinks{ display:flex; flex-wrap:wrap; gap: 10px 14px; color: var(--text-2); font-size: 13px; }
+.legal{ margin-top: 14px; color: var(--text-2); font-size: 12px; }
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero__grid{ grid-template-columns: 1fr; }
+  .toolsGrid{ grid-template-columns: 1fr; }
+  .grid4{ grid-template-columns: repeat(2, minmax(0,1fr)); }
+  .pillars{ grid-template-columns: repeat(2, minmax(0,1fr)); }
+  .articles{ grid-template-columns: repeat(2, minmax(0, 1fr)); }
+  .megamenu__grid{ grid-template-columns: 1fr; }
+  .megamenu__left{ border-right:0; border-bottom: 1px solid var(--border); }
+}
+@media (max-width: 640px){
+  .nav{ display:none; }
+  .brand{ min-width: auto; }
+  .heroTitle{ font-size: 30px; }
+  .articles{ grid-template-columns: 1fr; }
+  .toolsList{ grid-template-columns: 1fr; }
+  .footerGrid{ grid-template-columns: 1fr; }
+  .cta__inner{ grid-template-columns: 1fr; }
+  .carBtn{ display:none; }
+}
+
*** End Patch
PATCH"}

